  where not exists (
    select 1 from ingredient i
    where i.household_id = '00000000-0000-0000-0000-0000000000aa'
      and i.deleted_at is null and i.match_text = m.mt
  );
  -- raise, not ASSERT: plpgsql.check_asserts can be disabled, and this
  -- check must never be.
  if missing is not null then
    raise exception
      'seed_measures: no live vocab ingredient for: %', missing;
  end if;
  select count(*) into n from ingredient_measure
  where household_id = '00000000-0000-0000-0000-0000000000aa' and deleted_at is null;
  raise notice 'seed_measures: % live template measures (% seeded)', n, 237;
end $$;

